//! Independent gravitational and levitational fields generated by Escentrons.
//!
//! These field types are heterogeneous and MUST NOT be added to one another.
//! Source contributions are accumulated only within their own field type.
//! Converting either field into an acceleration is intentionally unspecified.
use crate::{ModelConstants, ParticleState, ValidationError, Vector3};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum FieldError {
    InvalidInput(ValidationError),
    CoincidentPositions,
    NonFiniteResult,
}

impl From<ValidationError> for FieldError {
    fn from(value: ValidationError) -> Self { Self::InvalidInput(value) }
}

impl std::fmt::Display for FieldError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidInput(err) => err.fmt(f),
            Self::CoincidentPositions => write!(f, "field undefined at a source position"),
            Self::NonFiniteResult => write!(f, "field calculation exceeded finite numerical range"),
        }
    }
}

impl std::error::Error for FieldError {}

/// A gravitational field vector (inward toward its source).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GravitationalField(pub Vector3);

/// A levitational field vector (outward from its source).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct LevitationalField(pub Vector3);

/// Field values from a single Escentron, kept strictly separate.
/// Magnitudes are nonnegative; vectors encode directions.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SourceFields {
    pub distance: f64,
    pub gravitational_magnitude: f64,
    pub levitational_magnitude: f64,
    pub gravitational: GravitationalField,
    pub levitational: LevitationalField,
}

/// Independent superposition of same-kind fields from multiple sources.
/// There is intentionally no heterogeneous "net field".
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct FieldTotals {
    pub gravitational: GravitationalField,
    pub levitational: LevitationalField,
}

impl FieldTotals {
    pub const ZERO: Self = Self {
        gravitational: GravitationalField(Vector3::ZERO),
        levitational: LevitationalField(Vector3::ZERO),
    };
}

/// Evaluate magnitudes f_g = G*m/r² and f_l = G*p/r³.
/// Gravitational vectors point toward the source; levitational vectors point away.
pub fn field_at(
    source: &ParticleState,
    observation: Vector3,
    constants: &ModelConstants,
) -> Result<SourceFields, FieldError> {
    source.validate()?;
    constants.validate()?;
    if !observation.is_finite() {
        return Err(ValidationError::NotFinite("observation").into());
    }
    let dx = observation.x - source.position.x;
    let dy = observation.y - source.position.y;
    let dz = observation.z - source.position.z;
    if !dx.is_finite() || !dy.is_finite() || !dz.is_finite() {
        return Err(FieldError::NonFiniteResult);
    }
    let distance = dx.hypot(dy).hypot(dz);
    if distance == 0.0 { return Err(FieldError::CoincidentPositions); }
    if !distance.is_finite() { return Err(FieldError::NonFiniteResult); }

    let inv_r = 1.0 / distance;
    let gravitational_magnitude = ((constants.g * inv_r) * source.mass) * inv_r;
    let levitational_magnitude = (((constants.g * inv_r) * source.pulse) * inv_r) * inv_r;
    if !gravitational_magnitude.is_finite() || !levitational_magnitude.is_finite() {
        return Err(FieldError::NonFiniteResult);
    }
    let direction = Vector3::new(dx * inv_r, dy * inv_r, dz * inv_r);
    let gravitational = Vector3::new(
        -gravitational_magnitude * direction.x,
        -gravitational_magnitude * direction.y,
        -gravitational_magnitude * direction.z,
    );
    let levitational = Vector3::new(
        levitational_magnitude * direction.x,
        levitational_magnitude * direction.y,
        levitational_magnitude * direction.z,
    );
    if !gravitational.is_finite() || !levitational.is_finite() {
        return Err(FieldError::NonFiniteResult);
    }
    Ok(SourceFields {
        distance,
        gravitational_magnitude,
        levitational_magnitude,
        gravitational: GravitationalField(gravitational),
        levitational: LevitationalField(levitational),
    })
}

fn sum_vectors(a: Vector3, b: Vector3) -> Result<Vector3, FieldError> {
    let sum = Vector3::new(a.x + b.x, a.y + b.y, a.z + b.z);
    if !sum.is_finite() { return Err(FieldError::NonFiniteResult); }
    Ok(sum)
}

/// Sum gravitational contributions with gravitational contributions, and
/// levitational contributions with levitational contributions, at one point.
/// No response of any target Escentron is calculated here.
pub fn fields_at(
    sources: &[ParticleState],
    observation: Vector3,
    constants: &ModelConstants,
) -> Result<FieldTotals, FieldError> {
    constants.validate()?;
    if !observation.is_finite() {
        return Err(ValidationError::NotFinite("observation").into());
    }
    let mut result = FieldTotals::ZERO;
    for source in sources {
        let contribution = field_at(source, observation, constants)?;
        result.gravitational = GravitationalField(sum_vectors(
            result.gravitational.0, contribution.gravitational.0,
        )?);
        result.levitational = LevitationalField(sum_vectors(
            result.levitational.0, contribution.levitational.0,
        )?);
    }
    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn source_at(x: f64) -> ParticleState {
        ParticleState {
            position: Vector3::new(x, 0.0, 0.0),
            velocity: Vector3::ZERO,
            mass: 2.0,
            pulse: 6.0,
        }
    }
    fn constants() -> ModelConstants {
        ModelConstants {
            g: 1.0, k_g: 1.0, k_l: 1.0, k_k: 1.0, cosmic_energy: 100.0,
        }
    }
    fn approx(a: f64, b: f64) {
        assert!((a - b).abs() < 1e-12, "{a} is not close to {b}");
    }

    #[test]
    fn neutral_radius_has_equal_magnitudes_but_separate_fields() {
        let f = field_at(&source_at(0.0), Vector3::new(3.0, 0.0, 0.0), &constants()).unwrap();
        approx(f.gravitational_magnitude, 2.0 / 9.0);
        approx(f.levitational_magnitude, 2.0 / 9.0);
        approx(f.gravitational.0.x, -2.0 / 9.0);
        approx(f.levitational.0.x, 2.0 / 9.0);
    }

    #[test]
    fn near_and_far_do_not_combine_field_types() {
        let near = field_at(&source_at(0.0), Vector3::new(1.0, 0.0, 0.0), &constants()).unwrap();
        approx(near.gravitational_magnitude, 2.0);
        approx(near.levitational_magnitude, 6.0);
        let far = field_at(&source_at(0.0), Vector3::new(4.0, 0.0, 0.0), &constants()).unwrap();
        approx(far.gravitational_magnitude, 2.0 / 16.0);
        approx(far.levitational_magnitude, 6.0 / 64.0);
    }

    #[test]
    fn same_kind_fields_superpose_vectorially() {
        let sources = [source_at(-1.0), source_at(-2.0)];
        let totals = fields_at(&sources, Vector3::ZERO, &constants()).unwrap();
        approx(totals.gravitational.0.x, -2.5);
        approx(totals.levitational.0.x, 6.75);
    }

    #[test]
    fn opposite_sources_cancel_each_field_independently() {
        let sources = [source_at(-1.0), source_at(1.0)];
        let totals = fields_at(&sources, Vector3::ZERO, &constants()).unwrap();
        approx(totals.gravitational.0.x, 0.0);
        approx(totals.levitational.0.x, 0.0);
    }

    #[test]
    fn field_directions_are_three_dimensional() {
        let f = field_at(&source_at(0.0), Vector3::new(0.0, -4.0, 0.0), &constants()).unwrap();
        assert!(f.gravitational.0.y > 0.0);
        assert!(f.levitational.0.y < 0.0);
        approx(f.gravitational.0.x, 0.0);
    }

    #[test]
    fn coincident_points_are_rejected() {
        assert_eq!(
            field_at(&source_at(0.0), Vector3::ZERO, &constants()),
            Err(FieldError::CoincidentPositions)
        );
    }

    #[test]
    fn non_finite_observation_is_rejected() {
        assert_eq!(
            fields_at(&[], Vector3::new(f64::NAN, 0.0, 0.0), &constants()),
            Err(FieldError::InvalidInput(ValidationError::NotFinite("observation")))
        );
    }

    #[test]
    fn no_sources_produce_two_zero_fields() {
        assert_eq!(
            fields_at(&[], Vector3::ZERO, &constants()).unwrap(),
            FieldTotals::ZERO
        );
    }

    #[test]
    fn zero_g_produces_two_zero_fields() {
        let mut c = constants();
        c.g = 0.0;
        assert_eq!(
            fields_at(&[source_at(1.0)], Vector3::ZERO, &c).unwrap(),
            FieldTotals::ZERO
        );
    }
}
